  if (decision === "reject") {
    return {
      messages: toolCalls.map(tc =>
        new ToolMessage({ content: "用户拒绝了此操作", tool_call_id: tc.id! })
      ),
    };
  }

  return { messages: [] };  // 审核通过，不加消息，继续往下走
}

